func TestDefaultConfig_DoesNotEnableResourceConstantLabels(t *testing.T) {
	cfg := createDefaultConfig().(*Config)
	require.Len(t, cfg.Metrics.Readers, 1)
	require.NotNil(t, cfg.Metrics.Readers[0].Pull)
